INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace) VALUES(154968,'08179','CR-BM — Camí Ral de Barcelona a Manresa','sendero','senderos_osm','El Camí Ral de Barcelona a Manresa al seu pas per la Serra de l''Obac (Parc Natural de Sant Llorent del Munt i l''Obac) també era conegut com el Camí Ral de Coll de Daví.',41.6601457,1.9308318,'https://blocs.xtec.cat/camiraldecolldedavi/');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(154969,'08049','CR-MB — Camí Ral de Manresa a Berga','sendero','senderos_osm','Poc abans d''arribar a Puig-reig, el Camí Ral de Manresa a Berga (camí de ferradura) deixa el curs del riu Llobregat per enfilar-se suaument a la carena. Passa per l''Hostal de Ferriols, la Capella del Roseret, l''Hostal Nou, Casserres i la Casa de Graugés.',42.0105003,1.8611736);
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace) VALUES(154970,'08139','CR-BB — Camí Ral de Barcelona a Berga','sendero','senderos_osm','Aquest camí era una drecera del camí principal de Barcelona a Manresa (camí ral de coll de Daví) i de Manresa a Berga (el que remuntava el curs del riu Llobregat). L''utilitzaven els viatgers que volien anar a Berga sense passar per Manresa.',41.7118722,1.9595202,'https://amagatallsdesantllorenc.blogspot.com/2020/07/el-cami-ral-de-barcelona-berga-al-seu.html');
