INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace) VALUES(154985,'08111','VR-BV — Variant del Camí Ral de Barcelona a Vic','sendero','senderos_osm','El camí ral de Barcelona a Vic té el seu antecedent en la via romana que comunicava les ciutats d''Ausa i Barcino passant per la vall del Congost. Durant l''edat mitjana, va construir-se una variant que sortia de Vic pel pont del Remei i passa pel coll de M',41.8705738,2.2477205,'https://patrimonicultural.diba.cat/element/cami-antic-de-vic-a-barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,enlace) VALUES(154986,'08254','CR-VO — Camí Ral de Vic a Olot','sendero','senderos_osm','El camí ral de Vic a Olot s''identifica com la Via o "Strata Francisca" (o camí de França), d''origen prehistòric o romà, esmentada des del segle X i citada repetidament fins al XV. Venia de França pel coll d''Ares i traspassava el Collsacabra pel grau de Fa',42.0553084,2.372252,'https://ca.turismegarrotxa.com/la-garrotxa/cultura/camins-historics/cami-ral-vic-olot/');
