INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud) VALUES(155020,'18180','Integral de Sierra Nevada','sendero','senderos_osm','La mayoría de los picos de más de 3.000 m de altitud de Sierra Nevada. SÓLO VERANO. MUY EXIGENTE. 3/4 ETAPAS. Admite multitud de variantes y atajos. Most 3000+ m peaks in Sierra Nevada. ONLY SUMMER. VERY DIFFICULT. 3/4 STAGES. Many variations can be done.',37.067875,-3.3469502);
