-- limpiar relleno: scores <=16 en munis sin ningún sendero real
DELETE FROM puntuaciones WHERE categoria='senderismo' AND puntuacion<=16 AND codigo_ine NOT IN (SELECT DISTINCT codigo_ine FROM entidades WHERE tipo='sendero');

-- descripciones para senderos curados sin descripción
UPDATE entidades SET descripcion='Ruta de senderismo en '||(SELECT nombre FROM municipios mm WHERE mm.codigo_ine=entidades.codigo_ine)||' ('||(SELECT provincia FROM municipios mm WHERE mm.codigo_ine=entidades.codigo_ine)||').' WHERE tipo='sendero' AND fuente='excel_curado' AND (descripcion IS NULL OR length(descripcion)<10);
